    async def terms(self) -> SignupTerms:
        """GET /v1/terms: {version, url}: the terms a new account accepts; an empty version means none are asked. Request: none."""
        return await self._request("terms", "/v1/terms")

    async def plans(self) -> BillingPlansResp:
        """GET /v1/plans: {plans, quote}: every plan and Quote plan with its price; with a session, what this account can buy. Request: none."""
        return await self._request("plans", "/v1/plans")

    async def wallet_login(self, body: WalletLoginReq) -> WalletChallengeResp | SignupSessionResp:
        """POST /v1/auth/wallet: {nonce_token, message} for "challenge"; {session_token, account} for "verify". Request: {step, wallet}: step "challenge" answers a message to sign; step "verify" takes nonce_token and signature (and pow on a first sign-in)."""
        return await self._request("wallet_login", "/v1/auth/wallet", body=body)

    async def pin_start(self, body: SignupPinStartReq) -> SignupPinStartResp:
        """POST /v1/login/pin: {pin_token}: a six-digit code is mailed; the answer is the same for every address. Request: {email}, and pow for an address with no account yet."""
        return await self._request("pin_start", "/v1/login/pin", body=body)

    async def pin_verify(self, body: SignupPinVerifyReq) -> SignupSessionResp:
        """POST /v1/login/pin/verify: {session_token, account}. Request: {pin_token, code}."""
        return await self._request("pin_verify", "/v1/login/pin/verify", body=body)

    async def logout(self) -> None:
        """POST /v1/logout: 204, no body: every session of the account ends. Request: none."""
        return await self._request("logout", "/v1/logout")

    async def wallet_link(self, body: WalletLinkReq) -> WalletChallengeResp | WalletLinkedResp:
        """POST /v1/account/link-wallet: {nonce_token, message} for "nonce"; the account with a new session_token for "link" (the old sessions end). Request: {step, wallet}: step "nonce" answers a message to sign; step "link" takes nonce_token and signature."""
        return await self._request("wallet_link", "/v1/account/link-wallet", body=body)

    async def reveal_key_secret(self, id: int) -> KeysSecretResp:
        """POST /v1/keys/{id}/secret: {available, raw_key}: the key's value while the account still holds it, else available false. Request: none."""
        return await self._request("reveal_key_secret", f"/v1/keys/{_int(id)}/secret")

    async def billing_checkout(self, body: BillingCheckoutReq | None = None) -> BillingCheckoutResp:
        """POST /v1/billing/checkout: {url, session_id, amount_minor, currency, recurring, term}: the card checkout page to open. Request: {tier} for a plan, or {module, plan} for a module plan; recurring for a card subscription."""
        return await self._request("billing_checkout", "/v1/billing/checkout", body={} if body is None else body)

    async def billing_crypto_intent(self, body: CryptoIntentReq | None = None) -> CryptoIntentResp:
        """POST /v1/billing/crypto-intent: one on-chain payment to make: recipient, amount, reference, expiry, and a ready transaction when payer is given. Request: {tier} or {module, plan}; months, mint (USDC or USDT) and the paying wallet as payer."""
        return await self._request("billing_crypto_intent", "/v1/billing/crypto-intent", body={} if body is None else body)

    async def billing_portal(self, *, module: str | None = None) -> BillingPortalResp:
        """POST /v1/billing/portal: {url}: the card provider's page for the subscription. Request: none; ?module=."""
        return await self._request("billing_portal", "/v1/billing/portal", query={"module": module})

    async def billing_cancel_renewal(self, *, module: str | None = None) -> BillingRenewalView:
        """POST /v1/billing/renewal: {module, renews, ends_at}: the renewal is cancelled, the term runs to its end; 409 when there is none. Request: none; ?module=."""
        return await self._request("billing_cancel_renewal", "/v1/billing/renewal", query={"module": module})

    async def billing_resume_renewal(self, *, module: str | None = None) -> BillingRenewalView:
        """DELETE /v1/billing/renewal: {module, renews, ends_at}: the cancelled renewal is resumed; 409 when there is none. Request: none; ?module=."""
        return await self._request("billing_resume_renewal", "/v1/billing/renewal", query={"module": module})

    async def account_deletion(self) -> CloseDeletionView:
        """GET /v1/account/deletion: {confirm, blocked, keys, credits_remaining, terms}: what deleting the account would end. Request: none."""
        return await self._request("account_deletion", "/v1/account/deletion")

    async def account_payment_document(self, id: int) -> BillingDocumentResp:
        """GET /v1/payments/{id}/document: {pdf, page}: the card provider's receipt links; an on-chain payment is 404. Request: none."""
        return await self._request("account_payment_document", f"/v1/payments/{_int(id)}/document")
